---@class MatConvertDialog
---@field ScrollView                    	UnityEngine.RectTransform               
---@field CommonTabToggleLeft           	Engine.Modules.LuaBehaviour             
---@field GridView                      	SuperScrollView.LoopGridView                      
local MatConvertDialog = Class("MatConvertDialog")

function MatConvertDialog:__init()
    self._selectId = nil
    self.isAscOrder = true ---升序
    self._goodsId = nil
    self.__toggleAction = nil
    self.filterType = FilterType.FilterDefault
    self.defaultImage = nil
    self.rareImage = nil
    self.__toggleFilterAction = nil
    self.data = nil
    self.__eventHandler = nil
    self.gainIdGroup = {} ---合成结果集合的数据
    self.consume = {}
end

function MatConvertDialog:__delete()
    self._selectId = nil
    self._goodsId = nil
    self.isAscOrder = nil
    self.controller = nil
    self.__toggleAction = nil
    self.defaultImage = nil
    self.rareImage = nil
    self.__toggleFilterAction = nil
    self.data = nil
    self.__eventHandler = nil
    self.gainIdGroup = nil ---合成结果集合的数据
    self.consume = nil
end

function MatConvertDialog:ConstructGroup()
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    local setting = settingMgr:GetSetting(AutoIds.IdSetting411, "MatCompositeVo")
    local tableSettings = setting:GetAll()
    for _, vo in pairs(tableSettings) do
        local gainId = vo.gainVo.goodsId
        self.gainIdGroup[tostring(gainId)] = clone(vo)
    end
end

function MatConvertDialog:Awake()
    self:ConstructGroup()
    self.__eventHandler = Events.AddListener(Constants.EventNames.UIEventCompositeFreshGridView, function()
        ---刷新gridview列表数据
        ---@type SuperScrollView.LoopStaggeredGridView
        local gridView = self.GridView
        GameUtils.ReloadData(gridView, nil)
    end)

    self:FillTogs()
    self._selectId = Constants.MatConvertType.Card ---第一个类别
    self.data = self:GetData()
    self:FreshGridView()

    KTool.SetActive(self.CommonFilterNode, false)
    --[[
    local commonFilterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode, CommonFilterMB)
    if commonFilterNodeEnv then
        --- 回调函数
        commonFilterNodeEnv:SetCallback(
            self:GetData(),
                function(data)
                    self.data = data
                    self:FreshGridView()
                end, 
                Constants.UISortType.Convert)
    end
    ]]
end

function MatConvertDialog:FillTogs()
    local t = { 
        {
            text = localize('武装组件'),
            func = function()
                self._selectId = Constants.MatConvertType.Card
                self.data = self:GetData()
                self:FreshGridView()
            end,
        }
    }
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, "Game.Behaviours.CommonTabToggleLeft")
    if scr then
        scr:FillToggles(t)
    end
end

---ResetFilterIconState
---重置过滤的icon状态
---
function MatConvertDialog:ResetFilterIconState()
    self.defaultImage:SetRotationZ(180)
    self.rareImage:SetRotationZ(180)
    ---重置状态
    KTool.SetActive(self.defaultImage.gameObject, self.filterType == FilterType.FilterDefault)
    KTool.SetActive(self.rareImage.gameObject, self.filterType == FilterType.FilterRare)

    ---更新文字的高亮状态
    ---@type UnityEngine.UI.Text
    local rareText = self.RareButton:Find("Text"):GetComponent(typeof(Text))
    ---@type UnityEngine.UI.Text
    local levelText = self.LevelButton:Find("Text"):GetComponent(typeof(Text))
    if self.filterType == FilterType.FilterDefault then
        ---稀有度
        rareText.color = XLuaUtils.HexToColor('#27221f')
        levelText.color = XLuaUtils.HexToColor('#4b4b4b')
    elseif self.filterType == FilterType.FilterRare then
        rareText.color = XLuaUtils.HexToColor('#27221f')
        levelText.color = XLuaUtils.HexToColor('#4b4b4b')
    end
end

---FreshGridView
---刷新gridview列表数据
function MatConvertDialog:FreshGridView()
    --KTool.SetActive(self.FilterNode.gameObject, self._selectId ~= GainGoodTypeId)
    --KTool.SetActive(self.FilterNode.gameObject, false)
    --刷新列表
    --self.data = self:GetData()
    local len = table.length(self.data)
    self.consume = {}
    if len > 0 then
        local allData = self.gainIdGroup
        if allData then
            local function list_consume(data, gainId)
                ---@type MatCompositeVo
                local vo = allData[tostring(gainId)]
                if isTable(vo) then
                    table.insert(data, vo)
                    list_consume(data, table.takeFirst(vo.consume).goodsId)
                end
            end
            for i, vo in pairs(allData) do
                if #vo.consume == 1 then
                    local t = {}
                    list_consume(t, checkNumber(vo.gainVo.goodsId))
                    self.consume[tostring(vo.gainVo.goodsId)] = t
                end
            end
        end
    end
    if not self.isInitial then
        self.isInitial = true
        self.GridView:InitGridView(len, Bind(self, self.OnGetItemByIndex))
    else
        ---@type SuperScrollView.LoopStaggeredGridView
        local gridView = self.GridView
        GameUtils.ReloadData(gridView, len)
    end
end

---GetData
---获取不同类型的数据
function MatConvertDialog:GetData()
    local t = {}
    if self._selectId then
        if checkInt(self._selectId) == GainGoodTypeId then
            t = cardConfMgr:GetMaterialsByGoodsId(self._goodsId)
        else
            t = cardConfMgr:GetMaterialsByCompositeType(checkInt(self._selectId))
        end
    end
    --[[
    if self._selectId ~= GainGoodTypeId then
        ---排序的逻辑
        if self.filterType == FilterType.FilterDefault then
            ---初始排序
            SortByMember(t, "id", checkBool(self.isAscOrder))
        elseif self.filterType == FilterType.FilterRare then
            for i, v in pairs(t) do
                local vo = goodsConfMgr:GetGoodsVoById(v.gainVo.goodsId)
                v.quality = checkInt(vo.quality)
            end
            SortByMember(t, "quality", checkBool(self.isAscOrder))
        end
    end
    ]]
    return t
end

---GetBasicMultiplierByPosition
---获取基础的一阶的乘法系数
---@param position number
function MatConvertDialog:GetBasicMultiplierByPosition(listData, position)
    ---前面所有的位置
    local multiply = 1
    for i = 1, position do
        ---前面所有的位置
        ---@type MatCompositeVo
        local preVo = listData[i]
        local consume = table.takeFirst(preVo.consume)
        multiply = multiply * checkNumber(consume.goodsNum)
    end
    return multiply
end

---GetMaxGainNum
---获取最大的可合成的数量
---@param vo MatCompositeVo
function MatConvertDialog:GetMaxGainNum(vo)
    ---要合成的数据转化为基础的数量
    local num = checkNumber(vo.gainVo.goodsNum)
    local listData = self.consume[tostring(vo.gainVo.goodsId)]
    if isNull(listData) then
        return 0
    end
    local targetLevel = #listData---目标品阶
    --print(targetLevel)
    local multiply = self:GetBasicMultiplierByPosition(listData, targetLevel)
    local maxHave = 0
    for i = 1, targetLevel do
        ---@type MatCompositeVo
        local vo = listData[i]
        local consume = table.takeFirst(vo.consume)
        --print(consume.goodsId)
        local myNo = GoodsUtils.GetThingNo(checkInt(consume.goodsId))
        --print('------>>>', myNo)
        --print('------>>>',targetLevel, myNo, self:GetBasicMultiplierByPosition(listData,targetLevel - i))
        maxHave = maxHave + myNo * self:GetBasicMultiplierByPosition(listData, targetLevel - i)
    end
    local delta = num * multiply
    local maxNo = math.floor(maxHave / delta)
    --print('---->>>', maxNo)
    return maxNo
end

---OnGetItemByIndex
---@param listView SuperScrollView.LoopGridView
---@param index number
---@return SuperScrollView.LoopGridView
function MatConvertDialog:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end
    if self.data == nil then
        return nil
    end
    if #self.data < (index + 1) then
        return nil
    end
    local cell = listView:NewListViewItem(PrefabName)
    ---@type MatCompositeVo
    local vo = self.data[index + 1]
    if not isNull(vo) then
        ---@type Engine.Modules.LuaBehaviour
        local headNode = GetLuaBehaviour(cell.gameObject, CompositeCellNodePath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            --是否需要cell的init的逻辑
            headNode:Init()
        end
        if not KTool.IsNull(headNode) then
            ---@type MatCompositeCellMB
            local Env = headNode.Env
            local isComplex = false
            if #vo.consume == 1 and self.gainIdGroup[tostring(table.takeFirst(vo.consume).goodsId)] then
                isComplex = true
            end
            local maxNo = 0
            if isComplex then
                maxNo = self:GetMaxGainNum(vo)
            end
            Env:Reload(vo, isComplex, function(gainId)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICompositePreviewDialog, parameters = { gainId = gainId, data = self.gainIdGroup } })
            end, maxNo)
        end
    end
    return cell
end

---FreshUI
---重新刷新页面
---@param goodsId number 指定的道具id
---@param isInitial boolean 是否是第一次
function MatConvertDialog:FreshUI(goodsId, isInitial)
    goodsId = checkInt(goodsId)
    self.data = self:GetData()
    self:FreshGridView(isInitial)
end

function MatConvertDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type Engine.UI.UIArgument
        local argument = self.controller.Argument
        local goodsId = nil
        if isSet(argument, "parameters") then
            goodsId = checkInt(argument.parameters.goodsId)
        end
        self:FreshUI(goodsId, true)

    end))
    return coWait
end

function MatConvertDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.UIEventCompositeFreshGridView, self.__eventHandler)
        --self.FilterContainer.OnTabChangeEvent:RemoveListener(self.__toggleFilterAction)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MatConvertDialog